// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.cognitive.diimport com.roshan.persona.brain.agentic.LlmCallerimport com.roshan.persona.brain.context.BrainContextimport com.roshan.persona.brain.context.SessionIdimport com.roshan.persona.brain.persona.Personaimport com.roshan.persona.brain.persona.ResponseStyleimport com.roshan.persona.brain.persona.Toneimport com.roshan.persona.brain.persona.Verbosityimport com.roshan.persona.brain.persona.Vocabularyimport com.roshan.persona.cognitive.decision.CriteriaAnalyzerimport com.roshan.persona.cognitive.decision.DecisionMakerimport com.roshan.persona.cognitive.decision.PreferenceAlignerimport com.roshan.persona.cognitive.decision.RiskAssessorimport com.roshan.persona.cognitive.engine.ClarificationEngineimport com.roshan.persona.cognitive.engine.ConfidenceModulatorimport com.roshan.persona.cognitive.engine.UncertaintyAwarenessimport com.roshan.persona.cognitive.execution.AgenticExecutorInterfaceimport com.roshan.persona.cognitive.execution.BrainBackedAgenticExecutorimport com.roshan.persona.cognitive.execution.PlanExecutorBridgeimport com.roshan.persona.cognitive.execution.ReasoningCacheimport com.roshan.persona.cognitive.execution.ReasoningTraceStoreimport com.roshan.persona.cognitive.execution.ReplanningEngineimport com.roshan.persona.cognitive.model.CognitiveConfigimport com.roshan.persona.cognitive.planner.DecomposerLlmimport com.roshan.persona.cognitive.planner.FuzzyConstraintInterpreterimport com.roshan.persona.cognitive.planner.TaskDecomposerimport com.roshan.persona.cognitive.planner.TaskPlannerimport com.roshan.persona.cognitive.reasoning.ChainOfThoughtimport com.roshan.persona.cognitive.reasoning.ReasoningEngineimport com.roshan.persona.cognitive.reasoning.ReasoningLlmimport com.roshan.persona.cognitive.reasoning.SelfCorrectorimport com.roshan.persona.cognitive.solver.ConstraintSatisfierimport com.roshan.persona.cognitive.solver.MemoryRecallInterfaceimport com.roshan.persona.cognitive.solver.PatternMatcherimport com.roshan.persona.cognitive.solver.ProblemSolverimport com.roshan.persona.cognitive.solver.RecalledMemoryimport com.roshan.persona.cognitive.solver.SolverLlmimport com.roshan.persona.common.AppErrorimport com.roshan.persona.common.CorrelationIdimport com.roshan.persona.common.Resultimport com.roshan.persona.persona.masking.DynamicFillerEngineimport dagger.Moduleimport dagger.Providesimport dagger.hilt.InstallInimport dagger.hilt.components.SingletonComponentimport kotlinx.coroutines.Dispatchersimport timber.log.Timberimport javax.inject.Injectimport javax.inject.Singleton@Module@InstallIn(SingletonComponent::class)object CognitiveModule {    @Provides @Singleton    fun provideCognitiveConfig(): CognitiveConfig = CognitiveConfig()    // ─── Real LLM implementations using LlmCaller ──────────────────────────    @Provides @Singleton    fun provideReasoningLlm(llmCaller: LlmCaller): ReasoningLlm = ReasoningLlm { prompt, temperature ->        val context = createMinimalBrainContext()        when (val result = llmCaller.invoke(prompt, context)) {            is Result.Success -> result.data            is Result.Failure -> {                Timber.w("Reasoning LLM failed: ${result.error.message}")                "Unable to reason — LLM error: ${result.error.message}"            }            is Result.Partial -> result.data        }    }    @Provides @Singleton    fun provideDecomposerLlm(llmCaller: LlmCaller): DecomposerLlm = DecomposerLlm { goal, minTasks, maxTasks ->        val prompt = "Decompose this goal into $minTasks-$maxTasks sub-tasks as JSON array: $goal"        val context = createMinimalBrainContext()        when (val result = llmCaller.invoke(prompt, context)) {            is Result.Success -> result.data            is Result.Failure -> {                Timber.w("Decomposer LLM failed: ${result.error.message}")                "[]"            }            is Result.Partial -> result.data        }    }    @Provides @Singleton    fun provideSolverLlm(llmCaller: LlmCaller): SolverLlm = SolverLlm { prompt ->        val context = createMinimalBrainContext()        when (val result = llmCaller.invoke(prompt, context)) {            is Result.Success -> result.data            is Result.Failure -> {                Timber.w("Solver LLM failed: ${result.error.message}")                "Unable to solve — LLM error: ${result.error.message}"            }            is Result.Partial -> result.data        }    }    @Provides @Singleton    fun provideMemoryRecallInterface(        memoryInterface: com.roshan.persona.brain.memory.MemoryInterface,    ): MemoryRecallInterface = object : MemoryRecallInterface {        override suspend fun recall(query: String, k: Int): List<RecalledMemory> {            val recallResult = memoryInterface.recall(query, k)            return if (recallResult is Result.Success) {                recallResult.data.map { mem ->                    RecalledMemory(                        content = mem.content,                        relevanceScore = mem.importance,                        timestamp = mem.timestamp.toEpochMilli(),                    )                }            } else {                emptyList()            }        }    }    @Provides @Singleton    fun provideAgenticExecutorInterface(llmCaller: LlmCaller): AgenticExecutorInterface =        BrainBackedAgenticExecutor(llmCaller)    @Provides @Singleton    fun provideDynamicFillerEngine(): DynamicFillerEngine = DynamicFillerEngine()    // ─── Gatekeepers ───────────────────────────────────────────────────────    @Provides @Singleton    fun provideClarificationEngine(config: CognitiveConfig): ClarificationEngine =        ClarificationEngine(config, Dispatchers.Default)    @Provides @Singleton    fun provideUncertaintyAwareness(config: CognitiveConfig): UncertaintyAwareness =        UncertaintyAwareness(config)    @Provides @Singleton    fun provideConfidenceModulator(config: CognitiveConfig): ConfidenceModulator =        ConfidenceModulator(config)    // ─── Planning ──────────────────────────────────────────────────────────    @Provides @Singleton    fun provideTaskDecomposer(llm: DecomposerLlm, config: CognitiveConfig): TaskDecomposer =        TaskDecomposer(llm = llm, config = config, dispatcher = Dispatchers.Default)    @Provides @Singleton    fun provideTaskPlanner(decomposer: TaskDecomposer, config: CognitiveConfig): TaskPlanner =        TaskPlanner(decomposer = decomposer, config = config, dispatcher = Dispatchers.Default)    @Provides @Singleton    fun provideFuzzyConstraintInterpreter(): FuzzyConstraintInterpreter =        FuzzyConstraintInterpreter(Dispatchers.Default)    // ─── Reasoning ─────────────────────────────────────────────────────────    @Provides @Singleton    fun provideChainOfThought(llm: ReasoningLlm, config: CognitiveConfig): ChainOfThought =        ChainOfThought(llm = llm, config = config, dispatcher = Dispatchers.Default)    @Provides @Singleton    fun provideSelfCorrector(llm: ReasoningLlm, config: CognitiveConfig): SelfCorrector =        SelfCorrector(llm = llm, config = config, dispatcher = Dispatchers.Default)    @Provides @Singleton    fun provideReasoningEngine(chainOfThought: ChainOfThought, selfCorrector: SelfCorrector, config: CognitiveConfig): ReasoningEngine =        ReasoningEngine(chainOfThought = chainOfThought, selfCorrector = selfCorrector, config = config, dispatcher = Dispatchers.Default)    // ─── Decision ──────────────────────────────────────────────────────────    @Provides @Singleton    fun provideCriteriaAnalyzer(): CriteriaAnalyzer = CriteriaAnalyzer(Dispatchers.Default)    @Provides @Singleton    fun provideRiskAssessor(): RiskAssessor = RiskAssessor(Dispatchers.Default)    @Provides @Singleton    fun providePreferenceAligner(): PreferenceAligner = PreferenceAligner(Dispatchers.Default)    @Provides @Singleton    fun provideDecisionMaker(criteriaAnalyzer: CriteriaAnalyzer, riskAssessor: RiskAssessor, preferenceAligner: PreferenceAligner, confidenceModulator: ConfidenceModulator, config: CognitiveConfig): DecisionMaker =        DecisionMaker(criteriaAnalyzer = criteriaAnalyzer, riskAssessor = riskAssessor, preferenceAligner = preferenceAligner, confidenceModulator = confidenceModulator, config = config, dispatcher = Dispatchers.Default)    // ─── Problem Solving ───────────────────────────────────────────────────    @Provides @Singleton    fun providePatternMatcher(memory: MemoryRecallInterface, llm: SolverLlm): PatternMatcher =        PatternMatcher(memory = memory, llm = llm, dispatcher = Dispatchers.Default)    @Provides @Singleton    fun provideConstraintSatisfier(): ConstraintSatisfier = ConstraintSatisfier(Dispatchers.Default)    @Provides @Singleton    fun provideProblemSolver(patternMatcher: PatternMatcher, constraintSatisfier: ConstraintSatisfier): ProblemSolver =        ProblemSolver(patternMatcher = patternMatcher, constraintSatisfier = constraintSatisfier, dispatcher = Dispatchers.Default)    // ─── Execution ─────────────────────────────────────────────────────────    @Provides @Singleton    fun provideReasoningCache(config: CognitiveConfig): ReasoningCache = ReasoningCache(config)    @Provides @Singleton    fun provideReasoningTraceStore(config: CognitiveConfig): ReasoningTraceStore = ReasoningTraceStore(config)    @Provides @Singleton    fun provideReplanningEngine(taskPlanner: TaskPlanner, fillerEngine: DynamicFillerEngine, config: CognitiveConfig): ReplanningEngine =        ReplanningEngine(taskPlanner = taskPlanner, fillerEngine = fillerEngine, config = config, dispatcher = Dispatchers.Default)    @Provides @Singleton    fun providePlanExecutorBridge(agenticExecutor: AgenticExecutorInterface, replanningEngine: ReplanningEngine, config: CognitiveConfig): PlanExecutorBridge =        PlanExecutorBridge(agenticExecutor = agenticExecutor, replanningEngine = replanningEngine, config = config, dispatcher = Dispatchers.Default)    // ─── Helper ────────────────────────────────────────────────────────────    /**     * Create a minimal BrainContext for LLM calls.     * Uses default persona and device context.     */    private fun createMinimalBrainContext(): BrainContext {        return BrainContext(            correlationId = CorrelationId.generate(),            sessionId = SessionId("cognitive"),            timestamp = java.time.Instant.now(),            timezone = java.util.TimeZone.getDefault(),            activePersona = Persona(                id = "atlas",                displayName = "Atlas",                systemPromptTemplate = "You are Atlas, a reliable AI assistant.",                skillPreferences = emptyMap(),                responseStyle = ResponseStyle(                    tone = Tone.WITTY,                    verbosity = Verbosity.BALANCED,                    useEmoji = false,                    vocabulary = Vocabulary.TECHNICAL,                ),            ),            userContext = com.roshan.persona.brain.context.UserContext(                userId = "nous-user",                displayName = "User",                preferredLanguage = java.util.Locale.ENGLISH,                preferredResponseLength = com.roshan.persona.brain.context.ResponseLength.BALANCED,                skillPreferences = emptyMap(),                privacySettings = com.roshan.persona.brain.context.PrivacySettings(),                monthlyLlmBudgetUsd = 10f,                monthlyLlmSpentUsd = 0f,            ),            deviceContext = com.roshan.persona.brain.context.DeviceContext(                thermalStatus = com.roshan.persona.brain.context.ThermalStatus.NONE,                availableRamMb = 2048,                batteryLevel = 100,                isCharging = false,                isOnline = true,                networkType = com.roshan.persona.brain.context.NetworkType.WIFI,                gpuAvailable = false,                gpuVramMb = 0,            ),            conversationHistory = emptyList(),            pendingExpectation = null,            ambientContext = null,            budget = com.roshan.persona.brain.context.BrainBudget(),        )    }}